From c13d8c94efbfa4bb42e9d635cdf0a2d330827bdc Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:33:46 +0100
Subject: [PATCH] desktoppackage: animate size changes of panels that fit their
 content

When a panel set to fit its content got a new task or widget, it jumped
to its new size in a single frame. Now its length is animated with the
usual duration, so it grows and shrinks smoothly; other modes don't change.

BUG: 506137
---
 desktoppackage/contents/views/Panel.qml | 59 +++++++++++++++----------
 1 file changed, 35 insertions(+), 24 deletions(-)

diff --git a/desktoppackage/contents/views/Panel.qml b/desktoppackage/contents/views/Panel.qml
index aea1844c5b..a37d9188f1 100644
--- a/desktoppackage/contents/views/Panel.qml
+++ b/desktoppackage/contents/views/Panel.qml
@@ -272,34 +272,45 @@ Item {
         adjustPrefix();
     }

-    Binding {
-        target: panel
-        property: "length"
-        when: root.containment
-        value: {
-            if (!root.containment) {
-                return;
-            }
-            if (root.verticalPanel) {
-                if (root.containment.Layout.fillHeight) {
-                    if (panel.lengthMode == Panel.Custom) {
-                        return panel.maximumHeight
-                    } else {
-                        return panel.screenGeometry.height
-                    }
+    property int contentLength: {
+        if (!root.containment) {
+            return 0;
+        }
+        if (root.verticalPanel) {
+            if (root.containment.Layout.fillHeight) {
+                if (panel.lengthMode == Panel.Custom) {
+                    return panel.maximumHeight
+                } else {
+                    return panel.screenGeometry.height
                 }
-                return root.containment.Layout.preferredHeight
-            } else {
-                if (root.containment.Layout.fillWidth) {
-                    if (panel.lengthMode == Panel.Custom) {
-                        return panel.maximumWidth
-                    } else {
-                        return panel.screenGeometry.width
-                    }
+            }
+            return root.containment.Layout.preferredHeight
+        } else {
+            if (root.containment.Layout.fillWidth) {
+                if (panel.lengthMode == Panel.Custom) {
+                    return panel.maximumWidth
+                } else {
+                    return panel.screenGeometry.width
                 }
-                return root.containment.Layout.preferredWidth
             }
+            return root.containment.Layout.preferredWidth
         }
+    }
+
+    // Panels that fit their content grow and shrink smoothly
+    Behavior on contentLength {
+        enabled: panel.lengthMode === Panel.FitContent
+        NumberAnimation {
+            duration: Kirigami.Units.longDuration
+            easing.type: Easing.OutCubic
+        }
+    }
+
+    Binding {
+        target: panel
+        property: "length"
+        when: root.containment
+        value: root.contentLength
         restoreMode: Binding.RestoreBinding
     }

-- 
